updateItem:(id,patch)=>commit(()=>{const it=project.items.find(i=>i.id===id);if(!it)throw Error('请先选择家具');const allowed=['name','w','d','h','x','z','rotation','color','material','price','y','wall','wallOffset'];for(const k of allowed)if(k in patch){let v=patch[k];if(['w','d','h','x','z','rotation','price','y','wall','wallOffset'].includes(k)){if(v===null&&k==='price'){it.price=null;continue;}v=Number(v);if(!Number.isFinite(v))throw Error('请输入有效数字');if(['w','d','h'].includes(k))v=clamp(v,k==='d'?20:10,6000);if(k==='x'||k==='z')v=clamp(v,-6000,20000);if(k==='price')v=clamp(v,0,10000000);}if(k==='name')v=String(v).slice(0,60);if(k==='color'&&!/^#[\da-f]{6}$/i.test(v))throw Error('颜色格式无效');if(k==='material'){if(v==='wood')v='board-oak';const finish=finishesFor(it.type,CATALOG).find(f=>f.id===v);if(!finish)throw Error('请为这件家具选择适合的板材、织物或金属饰面');if(!('color'in patch))it.color=finish.color;}it[k]=v;}if(it.mount==='wall'&&('x'in patch||'z'in patch)&&!('wall'in patch)&&!('wallOffset'in patch))snapToWall(it,it.x,it.z);else attachWallItem(it,project.structure);}),
removeItem:id=>commit(()=>{project.items=project.items.filter(i=>i.id!==id);selectedId=null;}),duplicateItem:id=>commit(()=>{const it=project.items.find(i=>i.id===id);if(!it)throw Error('请先选择家具');const next={...copy(it),id:uid('item'),x:it.x+200,z:it.z+200,name:it.name+' 副本'};if(next.mount==='wall'){delete next.wall;delete next.wallOffset;attachWallItem(next,project.structure,{items:project.items,place:true});}project.items.push(next);selectedId=next.id;}),
addOpening:kind=>commit(()=>{kind=/door/.test(kind)?'doors':'windows';const s=project.structure;const wall=kind==='doors'?s.vertices.length-2:0,p=openingPosition(s,{wall,offset:0});s[kind].push({id:uid(kind==='doors'?'door':'window'),wall,offset:p.len/2,width:kind==='doors'?800:1200,height:kind==='doors'?2100:1300,sill:kind==='doors'?0:900,depth:200,hinge:'left',swing:'in'});}),
updateOpening:(kind,id,patch)=>commit(()=>{kind=/door/.test(kind)?'doors':'windows';const o=project.structure[kind].find(i=>i.id===id);if(!o)throw Error('门窗不存在');for(const key of ['wall','offset','width','height','sill','depth','hinge','swing'])if(key in patch)o[key]=['hinge','swing'].includes(key)?patch[key]:Number(patch[key]);}),
removeOpening:(kind,id)=>commit(()=>{kind=/door/.test(kind)?'doors':'windows';project.structure[kind]=project.structure[kind].filter(i=>i.id!==id);}),
setView:next=>{if(!['3d','plan','front','right','eye'].includes(next))return;view=next;plan.style.display=view==='plan'?'block':'none';if(renderer)renderer.domElement.style.display=view==='plan'?'none':'block';resetCamera();resize();emit(false,false);},
setTool:next=>{tool=next;emit(false,false);},
undo:()=>{if(!history.length)return;future.push(copy(project));project=history.pop();selectedId=project.items.some(i=>i.id===selectedId)?selectedId:null;materialCache.clear();rebuild();applyLighting();emit(true);},
redo:()=>{if(!future.length)return;history.push(copy(project));project=future.pop();materialCache.clear();rebuild();applyLighting();emit(true);},
applyStyle:id=>commit(()=>{const style=styles[id];if(!style)return;const tile=style.floorType==='tile';Object.assign(project.structure,{wallColor:style.wall,wallMaterial:'wall-paint',floorType:style.floorType,floorColor:style.floorColor,floorFinish:style.floorFinish,floorUnitWidth:tile?600:180,floorUnitLength:tile?600:1200,floorPattern:tile?'straight':'staggered',floorGap:tile?2:1,floorGroutColor:tile?'#b8bcb9':'#b0a899'});for(const it of project.items){const t=template(it.type);if(t?.material==='wood'){it.material=style.board;it.color=style.wood;it.surfaceColorVersion=3;}else if(t?.material==='fabric'||it.type==='rug')it.color=style.fabric;}materialCache.clear();}),
saveVariant:name=>{if(project.variants.length>=6)throw Error('最多保留 6 套方案，请先导出项目备份');const p=copy(project);delete p.variants;project.variants.push({id:uid('variant'),name:String(name||'方案 '+(project.variants.length+1)).slice(0,40),createdAt:new Date().toISOString(),project:p,metrics:copy(metrics)});emit(false);toast('方案已保存在本机');},
loadVariant:id=>commit(()=>{const v=project.variants.find(v=>v.id===id);if(!v)throw Error('没有找到方案');const variants=project.variants;project=validateProject({...v.project,variants});selectedId=null;materialCache.clear();applyLighting();resetCamera();}),
deleteVariant:id=>{project.variants=project.variants.filter(v=>v.id!==id);emit(false);},
